<script setup lang="ts">
import{qualityInventoryEntry,type QualityInventoryEntry}from'./quality-source-entry';
import{useInventoryCountSources}from'./use-inventory-count-sources';
import{useInventoryDirectory}from'./use-inventory-directory';import InventoryDirectoryControls from'./InventoryDirectoryControls.vue';
import InventoryChoicePicker from'./InventoryChoicePicker.vue';
import{useInventoryLedger}from'./use-inventory-ledger';
import{useInventoryQueue}from'./use-inventory-queue';
import{useInventoryCommand}from'./use-inventory-command';import{useSalesScope as useInventoryScope}from'./use-sales-scope';import {ref,computed,onMounted,watch} from 'vue';
import {Package,Plus,ArrowLeft,RefreshCw,X,ClipboardList,ArrowDownToLine,ArrowUpFromLine} from '@lucide/vue';
import InventoryIssueAdjustment from './InventoryIssueAdjustment.vue';
const props=defineProps<{staff:any;sourceEntry?:QualityInventoryEntry|null}>(),emit=defineEmits(['unauthorized','return-quality']);
const clinics=ref<any[]>([]),clinic=ref(''),functions=ref<string[]>([]),section=ref('stock'),materials=ref<any[]>([]),suppliers=ref<any[]>([]),recipients=ref<any[]>([]),counts=ref<any[]>([]),detail=ref<any>(null),countDetail=ref<any>(null),preview=ref<any>(null);
const loading=ref(false),working=ref(false),ready=ref(false),error=ref(''),retryConfirmed=ref(false),mode=ref(''),form=ref<any>({}),selected=ref<string[]>([]),today=ref(''),issueOriginalTime=ref(''),issueHistories=ref<Record<string,any>>({}),issueAdjustmentRequired=ref(false);
const identity=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]),scope=useInventoryScope(()=>JSON.stringify([identity(),clinic.value])),authScope=useInventoryScope(identity);const command=useInventoryCommand({owner:()=>props.staff?.accountId&&props.staff?.employeeId?props.staff:null,storage:()=>sessionStorage,read:path=>request(path),send:(path,body)=>request(path,body),completed:async(path,result)=>{const current=authScope.capture();mode.value='';preview.value=null;await refresh(true);if(!current())return;if(result.stockId)await selectStock(result.stockId);if(current()&&path==='/counts')await selectCount(result.id);}}),{pending,notice,error:commandError}=command,busy=computed(()=>working.value||command.busy.value||ledger.loading.value||countSources.loading.value);
const queue=useInventoryQueue({account:()=>props.staff,clinic:()=>clinic.value,read:(p,signal)=>request(p,undefined,signal),invalidated:(status)=>{detail.value=null;countDetail.value=null;preview.value=null;selected.value=[];if(status===401||status===403){mode.value='';materials.value=[];suppliers.value=[];recipients.value=[];counts.value=[];functions.value=[];}}}),stocks=queue.items,{thresholdOn,threshold,expiryOn,expiryThrough}=queue;
watch(()=>queue.dirty.value,v=>{if(v)selected.value=[];},{flush:'sync'});
async function queryStocks(){selected.value=[];detail.value=null;await queue.load();}
async function clearStockFilters(){selected.value=[];detail.value=null;await queue.clearFilters();}
const countSources=useInventoryCountSources({preview,context:()=>JSON.stringify([identity(),clinic.value,section.value,mode.value]),read:(p,signal)=>request(p,undefined,signal),invalidated:status=>{mode.value='';form.value={};if(status===401||status===403){countDetail.value=null;detail.value=null;functions.value=[];}}});
const ledger=useInventoryLedger({detail,context:()=>JSON.stringify([identity(),clinic.value,section.value]),read:(p,signal)=>request(p,undefined,signal),invalidated:()=>{issueHistories.value={};preview.value=null;mode.value='';}});

function directoryModel(kind:'materials'|'suppliers'|'counts'){return useInventoryDirectory({account:()=>props.staff,clinic:()=>clinic.value,kind,read:(p,signal)=>request(p,undefined,signal),invalidated:(status)=>{if(status===401||status===403){detail.value=null;countDetail.value=null;preview.value=null;mode.value='';functions.value=[];materials.value=[];suppliers.value=[];recipients.value=[];}else if(status===409&&kind==='counts'){countDetail.value=null;preview.value=null;}}});}
const materialDirectory=directoryModel('materials'),supplierDirectory=directoryModel('suppliers'),countDirectory=directoryModel('counts'),directory=computed(()=>section.value==='catalogue'?materialDirectory:section.value==='suppliers'?supplierDirectory:section.value==='counts'?countDirectory:null);
watch(section,()=>{if(ready.value&&clinic.value&&directory.value)void directory.value.load();});

const has=(f:string)=>functions.value.includes(f),fmt=(n:any)=>n===null||n===undefined?'待核实':String(n).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,''),short=(s:string)=>s.slice(0,8).toUpperCase();
const local=(s?:string)=>new Date((s?Date.parse(s):Date.now()-1000)+8*3600000).toISOString().slice(0,19).replace(/:00$/,''),instant=(s:string)=>new Date(s+'+08:00').toISOString();
const full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
const receiptMaterial=ref<any>(null),receiveSession=ref(0),selectedMaterial=computed(()=>receiptMaterial.value);
function selectReceiveMaterial(v:any){if(mode.value!=='receive')return;receiptMaterial.value=v;form.value={...form.value,materialId:v?.id||'',materialVersion:v?.version,quantity:'',unitPrice:'',batch:'',expiresOn:'',batchNote:'',pendingNote:'',sourceReference:'',actualConfirmed:false};}
function selectReceiveSupplier(v:any){if(mode.value!=='receive')return;form.value={...form.value,supplierId:v?.id||'',supplierVersion:v?.version,unitPrice:'',pendingNote:'',sourceReference:'',actualConfirmed:false};}
const choiceRead=(p:string,signal:AbortSignal)=>request(p,undefined,signal);

const headings:Record<string,string>={material:'维护物资目录',supplier:'维护供应商',receive:'登记实际到货入库',issue:'登记实际领用',price:'补充 / 更正入库价格',count:'保存盘点基准',observe:'登记实际清点',apply:'核实差异并调整'};
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function request(path:string,body?:any,signal?:AbortSignal){const current=authScope.capture(),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000),abort=()=>controller.abort();signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)abort();try{const r=await fetch('/api/v1/inventory'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:controller.signal});const b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&current())emit('unauthorized');throw new ApiError(r.status,b.message||'请求失败。');}return b;}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}}
const explain=(e:unknown)=>e instanceof Error?e.message:'操作失败。';

async function initialize(){const current=authScope.begin('initialize');loading.value=true;try{command.restore();const b=await request('/bootstrap');if(!current())return;functions.value=b.functions;clinics.value=b.clinics;clinic.value=props.sourceEntry?.clinicId||b.clinics[0]?.id||'';today.value=b.today;ready.value=true;if(props.sourceEntry)await readQualitySource();else await refresh();}catch(e){if(current())error.value=explain(e);}finally{if(current())loading.value=false;}}
async function readQualitySource(){if(!ready.value||!props.sourceEntry||busy.value||mode.value)return;let target:QualityInventoryEntry;try{target=qualityInventoryEntry(props.sourceEntry);if(!clinics.value.some(c=>c.id===target.clinicId))throw Error('当前账号没有原领用所属诊所的库存查看范围。');}catch(e){detail.value=null;error.value=explain(e);return;}clinic.value=target.clinicId;section.value='stock';detail.value=null;countDetail.value=null;issueHistories.value={};const current=scope.begin('qualitySource',()=>JSON.stringify([props.sourceEntry,section.value]));loading.value=true;error.value='';try{const r=await request('/issues/'+target.issueId+'/source?clinicId='+target.clinicId);if(!current())return;if(r.sourceIssue?.issue_id!==target.issueId||r.stock?.clinic_id!==target.clinicId||r.sourceIssue?.stock_id!==r.stock?.stock_id)throw Error('原领用回复不匹配，未显示。');detail.value=r;}catch(e:any){if(current()){detail.value=null;if([401,403].includes(e.status)){queue.reset(false);functions.value=[];materials.value=[];suppliers.value=[];recipients.value=[];counts.value=[];}error.value=explain(e);}}finally{if(current.active())loading.value=false;}}
function returnQuality(){if(busy.value||loading.value||mode.value||pending.value)return;emit('return-quality');}
watch(()=>JSON.stringify(props.sourceEntry),()=>{detail.value=null;if(ready.value&&props.sourceEntry)void readQualitySource();},{flush:'sync'});
async function refresh(force=false){if(force!==true&&(mode.value||command.busy.value))return;if(!ready.value)return initialize();if(!clinic.value)return;const current=scope.begin('refresh'),stockId=detail.value?.stock.stock_id,countId=countDetail.value?.count.stocktake_id;loading.value=true;error.value='';selected.value=[];try{const[loaded]=await Promise.all([queue.load(),directory.value?directory.value.load():Promise.resolve(true)]);if(!current())return;if(!loaded){detail.value=null;countDetail.value=null;return;}if(stockId&&detail.value?.stock.stock_id===stockId)await selectStock(stockId);if(current()&&countId&&countDetail.value?.count.stocktake_id===countId)await selectCount(countId);}catch(e){if(current()){error.value=explain(e);stocks.value=[];detail.value=null;countDetail.value=null;}}finally{if(current.active())loading.value=false;}}
async function changeClinic(){detail.value=null;countDetail.value=null;selected.value=[];await refresh();}
async function selectStock(id:string){const current=scope.begin('selection',()=>section.value);error.value='';detail.value=null;countDetail.value=null;issueHistories.value={};try{const r=await request('/stocks/'+id);if(current())detail.value=r;}catch(e){if(current())error.value=explain(e);}}
async function loadIssueHistory(id:string,more=false){const current=scope.begin('history',()=>detail.value?.stock.stock_id||'');working.value=true;error.value='';try{const anchor=issueHistories.value[id],next=anchor?.nextVersion,r=await request('/issues/'+id+'/history'+(more&&next?'?'+new URLSearchParams({beforeVersion:String(next),atVersion:String(anchor.currentVersion),atFingerprint:anchor.historyFingerprint}):''));if(!current()||more&&issueHistories.value[id]!==anchor)return;issueHistories.value[id]={...r,items:more?[...issueHistories.value[id].items,...r.items]:r.items};}catch(e){if(current()){if([401,403,409].includes((e as any)?.status)){delete issueHistories.value[id];if([401,403].includes((e as any)?.status))detail.value=null;}error.value=explain(e);}}finally{if(current.active())working.value=false;}}
async function selectCount(id:string){const current=scope.begin('selection',()=>section.value);error.value='';countDetail.value=null;detail.value=null;preview.value=null;try{const r=await request('/counts/'+id);if(!current())return;countDetail.value=r;section.value='counts';}catch(e){if(current())error.value=explain(e);}}
function close(){if(busy.value||pending.value)return;mode.value='';preview.value=null;}
async function open(m:string,p?:any){if(pending.value||command.isBlocked()){error.value='请先核查原提交记录。';return;}error.value='';preview.value=null;
 if(m==='material')form.value={id:p?.material_id||null,version:Number(p?.row_version)||0,name:p?.name||'',classification:p?.classification||'',unit:p?.unit||'',specification:p?.specification||'',enabled:p?p.activation_arrangement==='enabled':true,distinctConfirmed:false,reason:''};
 if(m==='supplier')form.value={id:p?.supplier_id||null,version:Number(p?.row_version)||0,name:p?.name||'',contactInfo:p?.contact_info||'',cooperationInfo:p?.cooperation_info||'',pendingNote:p?.pending_note||'',enabled:p?p.activation_arrangement==='enabled':true,distinctConfirmed:false,reason:''};
 if(m==='receive'){receiptMaterial.value=null;receiveSession.value++;}
 if(m==='receive')form.value={materialId:'',supplierId:'',batch:'',expiresOn:'',quantity:'',receivedAt:local(),unitPrice:'',sourceReference:'',batchNote:'',pendingNote:'',actualConfirmed:false};
 if(m==='price')form.value={id:p.stock_receipt_id,version:Number(p.row_version),unitPrice:p.unit_price??'',pendingNote:p.pending_note||'',reason:''};
 if(m==='issue'){issueAdjustmentRequired.value=false;issueOriginalTime.value=p?.issued_at||'';const s=detail.value.stock;form.value={issueId:p?.issue_id||null,version:Number(p?.row_version)||0,stockId:s.stock_id,stockVersion:Number(s.row_version),recipientId:p?.recipient_id||'',unit:s.unit,quantity:p?.quantity||'',issuedAt:local(p?.issued_at),costUnitPrice:p?.cost_unit_price??'',pendingNote:p?.pending_note||'',actualConfirmed:false,reason:'',adjustmentIds:[]};}
 if(m==='count')form.value={stockIds:[...selected.value],scopeNote:''};
 if(m==='observe')form.value={version:Number(countDetail.value.count.row_version),lines:countDetail.value.lines.map((l:any)=>({id:l.stocktake_line_id,originalAt:l.counted_at||null,originalLocal:l.counted_at?local(l.counted_at):null,name:l.name,stockId:l.stock_id,batch:l.batch_reference,expiresOn:l.expires_on,unit:l.unit,quantity:l.counted_quantity??'',countedAt:local(l.counted_at||undefined),reason:l.reason_pending_note||''}))};
 if(m==='apply'){const target=countDetail.value?.count.stocktake_id,current=scope.begin('preview',()=>JSON.stringify([countDetail.value?.count.stocktake_id,section.value]));working.value=true;try{const r=await request('/counts/'+target+'/preview');if(!current())return;preview.value=r;form.value={verified:false,reason:''};}catch(e){if(current())error.value=explain(e);return;}finally{if(current.active())working.value=false;}}
 mode.value=m;
}
async function send(path:string,body:any,_label:string,retry=false){const current=authScope.capture();retryConfirmed.value=false;const saved=retry?await command.retry():await command.submit(path,body);if(current()&&(saved||pending.value)){mode.value='';preview.value=null;}}
async function retryOriginal(){if(!retryConfirmed.value||command.status.value?.state!=='not_found')return;await send('',null,'',true);}
async function save(){const f=form.value,id=crypto.randomUUID(),base={requestId:id};try{
 if(mode.value==='material')return await send('/materials',{...base,...f,clinicId:clinic.value},'物资目录已保存；数量不变。');
 if(mode.value==='supplier')return await send('/suppliers',{...base,...f,clinicId:clinic.value},'供应商资料已保存；原附件关联保留。');
 if(mode.value==='receive'&&(!f.materialId||!f.supplierId||!f.materialVersion||!f.supplierVersion||selectedMaterial.value?.id!==f.materialId))throw Error('请先查找并明确选择物资和供应商。');
 if(mode.value==='receive')return await send('/receipts',{...base,...f,clinicId:clinic.value,unit:selectedMaterial.value?.unit||'',receivedAt:instant(f.receivedAt),expiresOn:f.expiresOn||null,unitPrice:f.unitPrice===''?null:f.unitPrice},'实际到货已登记，库存和来源台账已共同保存。');
 if(mode.value==='price')return await send('/receipts/'+f.id+'/price',{...base,version:f.version,unitPrice:f.unitPrice,pendingNote:f.pendingNote,reason:f.reason},'价格资料已保存，原入库数量不变。');
 if(mode.value==='issue')return await send('/issues',{...base,...f,issuedAt:f.issueId?issueOriginalTime.value:instant(f.issuedAt),costUnitPrice:f.costUnitPrice===''?null:f.costUnitPrice},f.issueId?'领用更正已保存，只作用数量净差。':'实际领用已登记，来源原版和库存已共同保存。');
 const cid=countDetail.value?.count.stocktake_id;
 if(mode.value==='count')return await send('/counts',{...base,clinicId:clinic.value,...f},'盘点基准已保存，尚未改变库存。');
 if(mode.value==='observe')return await send('/counts/'+cid+'/observations',{...base,version:f.version,lines:f.lines.map((l:any)=>({id:l.id,countedAt:l.originalAt&&l.originalLocal===l.countedAt?l.originalAt:instant(l.countedAt),quantity:l.quantity,reason:l.reason}))},'实盘和待核实原因已保存，尚未调整库存。');
 if(mode.value==='apply')return await send('/counts/'+cid+'/apply',{...base,...f,version:preview.value.version,signature:preview.value.signature},'差异核实完成，已按净差调整当前库存。');
 }catch(e){error.value=explain(e);}}
const sourceName=(m:any)=>m.receipt_id?'实际入库':m.issue_revision_id?'领用 / 更正':m.stocktake_line_id?'盘点调整':m.delivery_line_id?'商品交付':'来源';
watch(()=>clinic.value,()=>{receiptMaterial.value=null;receiveSession.value++;mode.value='';form.value={};stocks.value=[];materials.value=[];suppliers.value=[];recipients.value=[];counts.value=[];detail.value=null;countDetail.value=null;preview.value=null;issueHistories.value={};selected.value=[];working.value=false;loading.value=false;},{flush:'sync'});
watch(identity,()=>{receiptMaterial.value=null;receiveSession.value++;clinics.value=[];clinic.value='';functions.value=[];stocks.value=[];materials.value=[];suppliers.value=[];recipients.value=[];counts.value=[];detail.value=null;countDetail.value=null;preview.value=null;issueHistories.value={};selected.value=[];mode.value='';form.value={};thresholdOn.value=false;threshold.value='';expiryOn.value=false;expiryThrough.value='';today.value='';issueOriginalTime.value='';issueAdjustmentRequired.value=false;section.value='stock';ready.value=false;working.value=false;loading.value=false;retryConfirmed.value=false;error.value='';void initialize();},{flush:'sync'});
defineExpose({refresh});onMounted(initialize);
</script>

<template><div class="inv-workspace">
 <section v-if="sourceEntry" class="b-card inv-block"><h2>从资料问题核对原领用</h2><p>仅查看会重新核验本店库存权限；更正仍须原领用维护权限。返回时将重新读取资料问题，不会自动标为已解决。</p><button class="b-button outline" :disabled="busy||loading||!!mode||!!pending" @click="returnQuality">返回原资料问题</button> <button class="b-button outline" :disabled="busy||loading||!!mode||!!pending" @click="readQualitySource">重新定位原领用</button></section>
 <section v-if="detail?.sourceIssue" class="b-card inv-block"><h2>已定位原领用 {{short(detail.sourceIssue.issue_id)}}</h2><p>完整编号：{{detail.sourceIssue.issue_id}}<br/>当前第{{detail.sourceIssue.row_version}}版 · 问题查看时第{{sourceEntry?.version}}版<br/>实际领用 {{full(detail.sourceIssue.issued_at)}} · {{detail.sourceIssue.recipient_name}}<br/>数量 {{fmt(detail.sourceIssue.quantity)}} {{detail.sourceIssue.unit}} · 成本单价 {{fmt(detail.sourceIssue.cost_unit_price)}}<br/>待核实：{{detail.sourceIssue.pending_note||'无待补说明'}}</p><p v-if="Number(detail.sourceIssue.row_version)!==sourceEntry?.version" class="b-alert warning">原领用已更新，以下为本次重新读取的当前版本；请回资料问题重新核实。</p><button v-if="has('stock.issue')" class="b-button outline" :disabled="busy||loading||!!mode||!!pending" @click="open('issue',detail.sourceIssue)">按原流程核实更正此领用</button><p v-else>当前仅可核对，请由有权限的物资管理人员补正。</p></section>
 <div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div>
 <div v-if="ledger.error.value" class="b-alert error" role="alert">{{ledger.error.value}}</div><div v-if="queue.error.value" class="b-alert error" role="alert">{{queue.error.value}}</div><div v-if="commandError" class="b-alert error" role="alert">{{commandError}}</div><section v-if="pending" class="b-alert warning"><strong>{{pending.summary}}</strong><template v-if="pending.phase==='pending'"><p>原办理结果不明，请先只读核实；不要另录同一来源。</p><button class="b-button outline" :disabled="busy" @click="retryConfirmed=false;command.verify()">只读核实原办理</button><div v-if="command.status.value?.state==='completed'"><p>查到原成功结果：{{short(command.status.value.resultId)}}，原第{{command.status.value.version}}版，保存时间{{full(command.status.value.completedAt)}}。对应原请求，不保证当前表单内容或后来状态。</p><button class="b-button" :disabled="busy" @click="command.acknowledge()">已核对原结果，仅清理提示</button></div><p v-else-if="command.status.value?.state==='not_found'">本次未见成功记录，可能仍在处理、未提交，或原办理只返回已有入库。未查到不等于库存未作用；请先查看原来源，查询不会补写或自动重试。</p><label v-if="command.status.value?.state==='not_found'" class="b-checkbox"><input type="checkbox" v-model="retryConfirmed" :disabled="busy"/><span>已核对原业务，确认按原请求编号和原内容重试</span></label><button v-if="command.status.value?.state==='not_found'" class="b-button" :disabled="busy||!retryConfirmed" @click="retryOriginal">按原请求重试办理</button></template><template v-else><p>{{pending.phase==='confirmed'?'业务已成功，仅本机提示未清理。':'原办理已被拒绝，仅本机提示未清理。'}}</p><button class="b-button" :disabled="busy" @click="command.cleanup()">仅清理本机提示</button></template></section>
 <div class="inv-toolbar"><label>所属诊所<select v-model="clinic" :disabled="busy||!!pending||!!mode" @change="changeClinic"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><span>数量随真实来源变动 · 价格未知保留待核实</span></div>
 <div class="f-tabs"><button :class="{active:section==='stock'}" @click="section='stock';detail=null;countDetail=null">库存与收发</button><button :class="{active:section==='catalogue'}" @click="section='catalogue';detail=null;countDetail=null">物资目录</button><button :class="{active:section==='suppliers'}" @click="section='suppliers';detail=null;countDetail=null">供应商</button><button :class="{active:section==='counts'}" @click="section='counts';detail=null">库存盘点</button></div>
 <div v-if="loading" class="b-help">正在读取当前库存…</div>
 <template v-if="detail"><button class="f-text" @click="detail=null"><ArrowLeft :size="16"/>返回库存列表</button><section class="b-card inv-summary"><div><div class="b-eyebrow">STOCK LEDGER · {{short(detail.stock.stock_id)}}</div><h2>{{detail.stock.name}}</h2><p>批次 {{detail.stock.batch_reference||'未提供'}} · 效期 {{detail.stock.expires_on||'待核实'}}</p></div><div class="inv-quantity"><strong>{{fmt(detail.stock.quantity)}}</strong><span>{{detail.stock.unit}} · 当前结存</span></div><button v-if="has('stock.issue')" class="b-button" :disabled="busy||!!pending" @click="open('issue')"><ArrowUpFromLine :size="17"/>登记领用</button></section>
 <section class="b-card inv-block"><h2>实际入库与价格资料</h2><p v-if="!detail.receipts.length" class="b-help">暂无该库存的入库来源。</p><article v-for="r in detail.receipts" :key="r.stock_receipt_id" class="inv-record"><div><strong>{{fmt(r.quantity)}} {{r.unit}} · {{full(r.received_at)}}</strong><p>{{r.source_reference}} · 原采用供应商：{{r.adopted_supplier_name||r.current_supplier_name}}</p><p>入库单价：{{r.unit_price===null?'待核实':fmt(r.unit_price)+' 元 / '+r.unit}}<span v-if="r.pending_note"> · {{r.pending_note}}</span></p></div><button v-if="has('stock.receive')" class="b-button outline small" :disabled="busy||!!pending" @click="open('price',r)">补价 / 更正价格</button></article><p class="b-help">已显示 {{detail.receipts.length}} / {{detail.ledger.receipts.total}} 笔入库</p><button v-if="detail.ledger.receipts.next" class="b-button outline small" :disabled="busy" @click="ledger.load('receipts')">加载更早入库</button></section>
 <section class="b-card inv-block"><h2>实际领用</h2><p v-if="!detail.issues.length" class="b-help">暂无领用登记。</p><template v-for="i in detail.issues" :key="i.issue_id"><article class="inv-record"><div><strong>{{i.recipient_name}} · {{fmt(i.quantity)}} {{i.unit}}</strong><p>{{full(i.issued_at)}} · 第 {{i.row_version}} 版</p><p>成本单价：{{i.cost_unit_price===null?'待核实':fmt(i.cost_unit_price)+' 元 / '+i.unit}} · {{i.pending_note||'无待补说明'}}</p></div><div class="inv-actions"><button class="b-button outline small" :disabled="busy||!!pending" @click="loadIssueHistory(i.issue_id)">查看领用原版</button><button v-if="has('stock.issue')" class="b-button outline small" :disabled="busy||!!pending" @click="open('issue',i)">核实更正</button></div></article><div v-if="issueHistories[i.issue_id]" class="inv-issue-history"><h3>领用 {{short(i.issue_id)}} 的原版历史</h3><article v-for="h in issueHistories[i.issue_id].items" :key="h.id"><strong>第{{h.version}}版 · {{fmt(h.quantity)}} {{h.unit}} · {{h.recipientName}}</strong><p>成本单价：{{h.unitPrice===null?'待核实':fmt(h.unitPrice)+'元'}} · 领用成本：{{h.costAmount===null?'待核实':h.costAmount+'元'}}<br/>本版库存差量：{{fmt(h.delta)}} {{h.unit}} · 实际领用：{{full(h.issuedAt)}}</p><p>本版登记：{{full(h.recordedAt)}} · {{h.recordedBy}}<br/>最初登记人：{{h.originalRegistrar}}<br/>核实说明：{{h.pendingNote||'无待补说明'}}<br/>本次原因：{{h.reason||'首次领用登记'}}</p><small v-if="h.adjustmentIds?.length">采用季度调整轮次：{{h.adjustmentIds.map((id:string)=>short(id)).join('、')}}</small></article><button v-if="issueHistories[i.issue_id].nextVersion" class="b-button outline small" :disabled="busy" @click="loadIssueHistory(i.issue_id,true)">加载更早领用原版</button><button class="f-text" @click="delete issueHistories[i.issue_id]">收起历史</button></div></template><p class="b-help">已显示 {{detail.issues.length}} / {{detail.ledger.issues.total}} 笔领用</p><button v-if="detail.ledger.issues.next" class="b-button outline small" :disabled="busy" @click="ledger.load('issues')">加载更早领用</button></section>
 <section class="b-card inv-block"><h2>数量变动台账</h2><div class="inv-table-wrap"><table><thead><tr><th>实际发生</th><th>来源</th><th>数量净变动</th><th>库存版本</th></tr></thead><tbody><tr v-for="m in detail.movements" :key="m.movement_id"><td>{{full(m.occurred_at)}}</td><td>{{sourceName(m)}}</td><td>{{fmt(m.quantity_delta)}} {{detail.stock.unit}}</td><td>{{m.stock_version_before}} → {{m.stock_version_after}}</td></tr></tbody></table></div><p class="b-help">已显示 {{detail.movements.length}} / {{detail.ledger.movements.total}} 条变动；价格更正不产生数量变动，来源历史保留。</p><button v-if="detail.ledger.movements.next" class="b-button outline small" :disabled="busy" @click="ledger.load('movements')">加载更早数量变动</button></section></template>
 <template v-else-if="section==='stock'"><section class="b-card inv-block"><div class="inv-section-head"><div><h2>诊所库存</h2><p>按物资、批次及效期区分数量。未知批次或效期保留为空。</p></div><button v-if="has('stock.receive')" class="b-button" :disabled="busy||!!pending" @click="open('receive')"><ArrowDownToLine :size="17"/>登记入库</button></div><form class="inv-query inv-queue-filters" @submit.prevent="queryStocks"><label>物资名称或批次<input v-model="queue.search.value" maxlength="100" placeholder="按字面查找名称或批次"/></label><label>每页批次<select v-model.number="queue.limit.value"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><label class="b-checkbox"><input v-model="thresholdOn" type="checkbox"/><span>检查本次数量阈值</span></label><label v-if="thresholdOn">物资总量低于<input v-model="threshold" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label v-if="thresholdOn">数量提示<select v-model="queue.low.value"><option value="all">全部</option><option value="low">低于阈值</option><option value="sufficient">达到阈值</option></select></label><label class="b-checkbox"><input v-model="expiryOn" type="checkbox"/><span>检查本次效期</span></label><label v-if="expiryOn">近效期截止日<input v-model="expiryThrough" type="date" :min="today" required/></label><label v-if="expiryOn">效期提示<select v-model="queue.expiry.value"><option value="all">全部</option><option value="expired">已过有效日期</option><option value="near">近效期</option><option value="missing">效期待核实</option><option value="outside_range">截止日之后</option></select></label><div class="inv-queue-buttons"><button class="b-button outline small" :disabled="queue.loading.value">查询 / 更新</button><button type="button" class="f-text" :disabled="queue.loading.value" @click="clearStockFilters">清空条件</button></div></form><p v-if="queue.dirty.value" class="b-alert warning">条件已更改，点击“查询 / 更新”后生效；当前结果和统计仍属上次查询。</p><div class="inv-queue-summary"><div><span>匹配批次</span><strong>{{queue.summary.value?.batches??'—'}}</strong></div><div><span>涉及物资</span><strong>{{queue.summary.value?.materials??'—'}}</strong></div><div><span>低于阈值的物资</span><strong>{{queue.summary.value?.lowMaterials??'—'}}</strong></div><div><span>已过期批次</span><strong>{{queue.summary.value?.expired??'—'}}</strong></div><div><span>近效期批次</span><strong>{{queue.summary.value?.near??'—'}}</strong></div><div><span>效期待核实批次</span><strong>{{queue.summary.value?.missing??'—'}}</strong></div></div><p class="b-help">统计覆盖名称或批次线索匹配的完整范围，在数量、效期提示筛选之前计算。数量阈值按本诊所同物资所有批次总量判断，未检查项显示“—”；不同单位不相加。</p>
 <div class="inv-table-wrap"><table><thead><tr><th v-if="has('stock.count')">盘点选择</th><th>物资 / 批次</th><th>效期</th><th>当前结存</th><th>本次提示</th><th></th></tr></thead><tbody><tr v-for="s in stocks" :key="s.stock_id"><td v-if="has('stock.count')"><input type="checkbox" v-model="selected" :disabled="queue.dirty.value||queue.loading.value" :value="s.stock_id" :aria-label="'选择盘点 '+s.name+' '+(s.batch_reference||'未提供批次')+' '+(s.expires_on||'效期待核实')+' '+short(s.stock_id)"/></td><td><strong>{{s.name}}</strong><small>{{s.batch_reference||'未提供批次'}} · {{s.specification||s.classification}}</small></td><td>{{s.expires_on||'待核实'}}</td><td><strong>{{fmt(s.quantity)}} {{s.unit}}</strong><small>同物资合计 {{fmt(s.material_total)}} {{s.unit}}</small></td><td><span v-if="s.lowQuantity" class="inv-warning">低于阈值</span><span v-if="s.expiryState==='expired'" class="inv-warning">已过有效日期</span><span v-if="s.expiryState==='near'" class="inv-warning">近效期</span><span v-if="s.expiryState==='missing'" class="inv-warning">效期待核实</span><span v-if="!s.lowQuantity&&s.expiryState==='not_selected'">未选择效期条件</span></td><td><button class="f-text" @click="selectStock(s.stock_id)">查看收发</button></td></tr></tbody></table><p v-if="!queue.loading.value&&!stocks.length" class="b-empty"><Package :size="28"/>当前条件下没有库存批次，可调整查询条件。</p></div><div class="inv-queue-footer"><span>已显示 {{stocks.length}} / {{queue.total.value}} 批次</span><button v-if="queue.next.value" class="b-button outline small" :disabled="queue.loading.value||queue.dirty.value" @click="queue.load(true)">{{queue.loading.value?'正在读取…':'继续加载库存'}}</button></div><div v-if="has('stock.count')" class="inv-count-action"><span>已选择 {{selected.length}} 项</span><button class="b-button outline" :disabled="!selected.length||selected.length>50||busy||!!pending||queue.dirty.value||queue.loading.value" @click="open('count')"><ClipboardList :size="17"/>保存盘点基准</button></div></section></template>
 <section v-else-if="section==='catalogue'" class="b-card inv-block"><div class="inv-section-head"><div><h2>物资目录</h2><p>目录不保存数量；已有引用的单位不能直接变更。</p></div><button v-if="has('material.manage')" class="b-button" :disabled="busy||!!pending" @click="open('material')"><Plus :size="17"/>新增物资</button></div><InventoryDirectoryControls :model="materialDirectory"/><article v-for="m in materialDirectory.items.value" :key="m.material_id" class="inv-record"><div><strong>{{m.name}}</strong><p>{{m.classification}} · {{m.unit}} · {{m.specification||'规格未提供'}}</p><span class="b-pill" :class="m.activation_arrangement==='enabled'?'active':''">{{m.activation_arrangement==='enabled'?'可供新选择':'已停用'}}</span></div><button v-if="has('material.manage')" class="b-button outline small" :disabled="busy||!!pending" @click="open('material',m)">维护资料</button></article><p v-if="!materialDirectory.loading.value&&!materialDirectory.items.value.length" class="b-empty">当前条件下没有物资。</p><div class="inv-queue-footer"><span>已显示 {{materialDirectory.items.value.length}} / {{materialDirectory.total.value}} 项</span><button v-if="materialDirectory.next.value" class="b-button outline small" :disabled="materialDirectory.loading.value||materialDirectory.dirty.value" @click="materialDirectory.load(true)">继续加载物资</button></div></section>
 <section v-else-if="section==='suppliers'" class="b-card inv-block"><div class="inv-section-head"><div><h2>供应商资料</h2><p>保留已有关联附件；本批支持基础资料和待补事项。</p></div><button v-if="has('supplier.manage')" class="b-button" :disabled="busy||!!pending" @click="open('supplier')"><Plus :size="17"/>新增供应商</button></div><InventoryDirectoryControls :model="supplierDirectory" supplier/><article v-for="s in supplierDirectory.items.value" :key="s.supplier_id" class="inv-record"><div><strong>{{s.name}}</strong><p>{{s.contact_info||'联系资料未提供'}}</p><p>{{s.cooperation_info||'合作资料未提供'}}</p><small>{{s.pending_note||'暂无待补说明'}} · 已有关联附件 {{s.file_count}} 份</small><p><span class="b-pill" :class="s.activation_arrangement==='enabled'?'active':''">{{s.activation_arrangement==='enabled'?'可供新选择':'已停用'}}</span></p></div><button v-if="has('supplier.manage')" class="b-button outline small" :disabled="busy||!!pending" @click="open('supplier',s)">维护资料</button></article><p v-if="!supplierDirectory.loading.value&&!supplierDirectory.items.value.length" class="b-empty">当前条件下没有供应商。</p><div class="inv-queue-footer"><span>已显示 {{supplierDirectory.items.value.length}} / {{supplierDirectory.total.value}} 项</span><button v-if="supplierDirectory.next.value" class="b-button outline small" :disabled="supplierDirectory.loading.value||supplierDirectory.dirty.value" @click="supplierDirectory.load(true)">继续加载供应商</button></div></section>
 <section v-else-if="section==='counts'" class="b-card inv-block"><template v-if="!countDetail"><div class="inv-section-head"><div><h2>库存盘点</h2><p>从库存列表选择范围并保存基准，再登记实盘和核实差异。</p></div><button class="b-button outline small" @click="section='stock'">选择盘点范围</button></div><InventoryDirectoryControls :model="countDirectory" counts/><article v-for="q in countDirectory.items.value" :key="q.stocktake_id" class="inv-record"><div><strong>盘点 {{short(q.stocktake_id)}} · {{q.line_count}} 项</strong><p>基准 {{full(q.baseline_at)}} · {{q.scope_note}}</p><span class="b-pill" :class="q.processed_at?'active':''">{{q.processed_at?'已核实作用，可继续复核':'待清点 / 核实'}}</span></div><button class="f-text" @click="selectCount(q.stocktake_id)">查看盘点</button></article><p v-if="!countDirectory.loading.value&&!countDirectory.items.value.length" class="b-empty">当前条件下没有盘点。保存基准本身不调整库存。</p><div class="inv-queue-footer"><span>已显示 {{countDirectory.items.value.length}} / {{countDirectory.total.value}} 项</span><button v-if="countDirectory.next.value" class="b-button outline small" :disabled="countDirectory.loading.value||countDirectory.dirty.value" @click="countDirectory.load(true)">继续加载盘点</button></div></template>
 <template v-else><button class="f-text" @click="countDetail=null"><ArrowLeft :size="16"/>返回盘点列表</button><div class="inv-section-head"><div><h2>盘点 {{short(countDetail.count.stocktake_id)}}</h2><p>基准 {{full(countDetail.count.baseline_at)}} · {{countDetail.count.scope_note}}</p></div><span class="b-pill" :class="countDetail.count.processed_at?'active':''">{{countDetail.count.processed_at?'已核实作用':'待核实'}}</span></div><div class="inv-table-wrap"><table><thead><tr><th>物资</th><th>固定基准</th><th>实际清点</th><th>本盘点已作用差</th><th>当前结存</th></tr></thead><tbody><tr v-for="l in countDetail.lines" :key="l.stocktake_line_id"><td><strong>{{l.name}}</strong><small>批次 {{l.batch_reference||'未提供'}} · 效期 {{l.expires_on||'待核实'}} · {{short(l.stock_id)}}</small><small>{{l.reason_pending_note||'尚未登记实盘原因'}}</small></td><td>{{fmt(l.baseline_quantity)}} {{l.unit}}</td><td>{{l.counted_quantity===null?'尚未清点':fmt(l.counted_quantity)+' '+l.unit}}<small>{{full(l.counted_at)}}</small></td><td>{{l.actual_adjustment===null?'尚未作用':fmt(l.actual_adjustment)}}</td><td>{{fmt(l.current_quantity)}} {{l.unit}}</td></tr></tbody></table></div><div v-if="has('stock.count')" class="inv-actions"><button class="b-button outline" :disabled="busy||!!pending" @click="open('observe')">登记 / 更正实盘</button><button class="b-button" :disabled="busy||!!pending||countDetail.lines.some((l:any)=>l.counted_quantity===null)" @click="open('apply')">预览差异与期间来源</button></div><p class="b-help">实盘保存不直接调整。核实后按“本次应有差异 − 本盘点已作用差”调整当前结存，不覆盖期间出入库。</p></template></section>
 <p v-if="!mode&&countSources.error.value" class="b-alert error" role="alert">{{countSources.error.value}}</p><div v-if="mode" class="b-backdrop"><form class="b-dialog inv-dialog" :class="{'inv-wide':mode==='apply'}" role="dialog" aria-modal="true" @submit.prevent="save"><button class="b-close" type="button" aria-label="关闭物资办理" :disabled="busy||!!pending" @click="close"><X :size="21"/></button><div class="b-eyebrow">INVENTORY OPERATIONS</div><h2>{{mode==='issue'&&form.issueId?'核实更正实际领用':headings[mode]}}</h2><div v-if="error" class="b-alert error" role="alert">{{error}}</div>
 <template v-if="mode==='material'||mode==='supplier'"><label>{{mode==='material'?'物资名称':'供应商名称'}}<input v-model="form.name" required maxlength="200"/></label><template v-if="mode==='material'"><div class="b-two-fields"><label>分类<input v-model="form.classification" required maxlength="100"/></label><label>计量单位<input v-model="form.unit" required maxlength="40"/></label></div><label>规格（可空）<input v-model="form.specification" maxlength="1500"/></label></template><template v-else><label>联系资料（可空）<textarea v-model="form.contactInfo" rows="2" maxlength="1500"/></label><label>合作资料（可空）<textarea v-model="form.cooperationInfo" rows="2" maxlength="1500"/></label><label>待补事项（可空）<textarea v-model="form.pendingNote" rows="2" maxlength="1500"/></label></template><label class="b-checkbox"><input v-model="form.enabled" type="checkbox"/><span>允许供新的业务选择；停用不删除历史。</span></label><label class="b-checkbox"><input v-model="form.distinctConfirmed" type="checkbox"/><span>如有同名资料，已核实这是不同物资或主体。</span></label><label v-if="form.id">更正原因<textarea v-model="form.reason" required maxlength="1500" rows="2"/></label><p class="b-help">共享资料已被多个诊所引用时，须具有全部相关诊所的维护权限。</p></template>
 <template v-if="mode==='receive'"><InventoryChoicePicker kind="materials" :account="props.staff" :clinic-id="clinic" :form-key="receiveSession" :disabled="busy||!!pending" :read="choiceRead" @selected="selectReceiveMaterial"/><InventoryChoicePicker kind="suppliers" :account="props.staff" :clinic-id="clinic" :form-key="receiveSession" :disabled="busy||!!pending" :read="choiceRead" @selected="selectReceiveSupplier"/><div class="b-two-fields"><label>实际到货数量（{{selectedMaterial?.unit||'先选物资'}}）<input v-model="form.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label>实际接收时间<input v-model="form.receivedAt" type="datetime-local" step="1" required/></label></div><label>到货凭据编号及行号<input v-model="form.sourceReference" required maxlength="500" placeholder="同一张凭据的不同物资行须可区分"/></label><div class="b-two-fields"><label>原批次（未知留空）<input v-model="form.batch" maxlength="200"/></label><label>原有效日期（未知留空）<input v-model="form.expiresOn" type="date"/></label></div><label>原批次及效期资料说明<textarea v-model="form.batchNote" rows="2" maxlength="1500"/></label><label>已核实入库单价（元 / {{selectedMaterial?.unit||'单位'}}，未知留空）<input v-model="form.unitPrice" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?"/></label><label>价格或资料待核实说明<textarea v-model="form.pendingNote" :required="form.unitPrice===''" maxlength="1500" rows="2"/></label><label class="b-checkbox"><input v-model="form.actualConfirmed" type="checkbox" required/><span>已核对实际接收数量、单位和到货凭据；未知价格未填零。</span></label></template>
 <template v-if="mode==='price'"><p class="b-help">只补充或更正原入库价格，数量及原到货时点保持。</p><label>已核实入库单价（元 / {{detail.stock.unit}}）<input v-model="form.unitPrice" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label>仍待核实事项（可空）<textarea v-model="form.pendingNote" rows="2" maxlength="1500"/></label><label>补价 / 更正依据<textarea v-model="form.reason" required rows="3" maxlength="1500"/></label></template>
 <template v-if="mode==='issue'"><div class="f-context">{{detail.stock.name}} · 当前 {{fmt(detail.stock.quantity)}} {{detail.stock.unit}}</div><label>实际领用人员<select v-model="form.recipientId" required><option value="">请选择实际领用人员</option><option v-for="r in recipients" :key="r.id" :value="r.id">{{r.name}}</option></select></label><div class="b-two-fields"><label>实际领用数量（{{form.unit}}）<input v-model="form.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label>实际领用时间<input v-model="form.issuedAt" type="datetime-local" step="1" :readonly="!!form.issueId" required/></label></div><label>已核实成本单价（元 / {{form.unit}}，未知留空）<input v-model="form.costUnitPrice" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?"/></label><label>成本及归属待核实说明<textarea v-model="form.pendingNote" :required="form.costUnitPrice===''" rows="2" maxlength="1500"/></label><label v-if="form.issueId||issueAdjustmentRequired">更正或闭季晚录依据<textarea v-model="form.reason" required rows="2" maxlength="1500"/></label><InventoryIssueAdjustment v-model="form.adjustmentIds" :stock-id="form.stockId" :issued-at="form.issueId?issueOriginalTime:form.issuedAt?instant(form.issuedAt):''" :issue-id="form.issueId" :disabled="busy||!!pending" @recipients="recipients=$event" @periods="issueAdjustmentRequired=$event.length>0"/><label class="b-checkbox"><input v-model="form.actualConfirmed" type="checkbox" required/><span>确已实际领用。领用不等于某次治疗的精确耗用或某位医生的成本。</span></label><p v-if="form.issueId" class="b-help">本批更正固定原库存和实际时点，只对数量净差作用库存，旧版继续保留。</p></template>
 <template v-if="mode==='count'"><p class="b-help">将保存已选 {{form.stockIds.length}} 项的当前数量、版本和基准时刻，不改变库存。</p><label>本次盘点范围说明<textarea v-model="form.scopeNote" required rows="3" maxlength="1500"/></label></template>
 <template v-if="mode==='observe'"><p class="b-help">按实际清点填写。保存只记录实盘和原因，核实调整在下一步。</p><div v-for="l in form.lines" :key="l.id" class="inv-observation"><strong>{{l.name}}</strong><p class="b-help">批次 {{l.batch||'未提供'}} · 效期 {{l.expiresOn||'待核实'}} · {{short(l.stockId)}}</p><div class="b-two-fields"><label>实际清点数量（{{l.unit}}）<input v-model="l.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" required/></label><label>实际清点时间<input v-model="l.countedAt" type="datetime-local" step="1" required/></label></div><label>核实原因或待处理事项<textarea v-model="l.reason" required rows="2" maxlength="1500"/></label></div></template>
 <template v-if="mode==='apply'&&preview"><p class="b-help">应有差异 D = 实盘 −（固定基准 + 期间净变动）。本次调整 = D − 本盘点已作用差 A。核实的是当前预览及来源版本。</p><article v-for="l in preview.lines" :key="l.id" class="inv-preview"><h3>{{l.name}} <small>{{l.unit}}</small></h3><p class="b-help">批次 {{l.batch||'未提供'}} · 效期 {{l.expiresOn||'待核实'}} · {{short(l.stockId)}}</p><div class="inv-math"><span>固定基准<strong>{{fmt(l.baseline)}}</strong></span><span>期间净变动<strong>{{fmt(l.period)}}</strong></span><span>实际清点<strong>{{fmt(l.counted)}}</strong></span><span>应有差异 D<strong>{{fmt(l.difference)}}</strong></span><span>已作用 A<strong>{{fmt(l.alreadyApplied)}}</strong></span><span class="inv-delta">本次调整<strong>{{fmt(l.delta)}}</strong></span></div><p>当前结存 {{fmt(l.current)}} → 调整后 {{fmt(l.after)}} {{l.unit}}</p><p v-if="l.blocked" class="b-alert warning">存在其他盘点调整，包含关系须继续核实。本批保持待处理，不自动调整。</p><details><summary>核对基准后来源（已显示 {{l.sources.length}} / {{l.sourceTotal}} 条）与实际清点时点 {{full(l.countedAt)}}</summary><p v-if="!l.sources.length" class="b-help">基准后无数量变动来源。</p><div v-for="s in l.sources" :key="s.movement_id" class="inv-source"><span>{{sourceName(s)}} · {{full(s.occurred_at)}}</span><strong>{{fmt(s.quantity_delta)}} {{l.unit}}</strong><small>{{s.stocktake_line_id?'盘点调整，单独核对，不计入普通期间净变动':s.within_counted_period?'计入本次期间净变动':'清点后发生，不计入期间净变动'}} · 库存版 {{s.stock_version_after}}</small></div><button v-if="l.sourceNext" type="button" class="b-button outline small" :disabled="busy||!!pending" @click="countSources.load(l.id)">{{countSources.loading.value?'正在读取来源…':'继续加载本项来源'}}</button></details></article><p v-if="countSources.error.value" class="b-alert error" role="alert">{{countSources.error.value}}</p><label>差异核实和本次调整依据<textarea v-model="form.reason" required rows="3" maxlength="2000"/></label><label class="b-checkbox"><input v-model="form.verified" type="checkbox" required/><span>已核实清点事实、期间来源和差异原因，同意按当前预览的净差调整。</span></label></template>
 <button class="b-button full" :disabled="busy||(mode==='receive'&&(!form.materialId||!form.supplierId))||(mode==='apply'&&preview?.lines.some((l:any)=>l.blocked))">{{busy?'正在保存…':mode==='observe'?'保存实盘，暂不调整':mode==='apply'?'确认按净差调整':mode==='count'?'确认保存盘点基准':'确认保存'}}</button>
 </form></div>
</div></template>

<style scoped>.inv-queue-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;align-items:end}.inv-queue-filters label{min-width:0;display:flex;flex-direction:column;gap:7px}.inv-queue-filters label.b-checkbox{flex-direction:row;align-items:center}.inv-queue-filters input:not([type=checkbox]),.inv-queue-filters select{box-sizing:border-box;width:100%;min-width:0}.inv-queue-buttons,.inv-queue-footer{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.inv-queue-footer{justify-content:space-between;margin-top:18px}.inv-queue-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.inv-queue-summary>div{padding:16px;border-radius:10px;background:#f3f7f2;min-width:0}.inv-queue-summary span{display:block;font-size:14px;color:#677761}.inv-queue-summary strong{display:block;font-size:25px;margin-top:8px;overflow-wrap:anywhere}@media(max-width:800px){.inv-queue-filters{grid-template-columns:minmax(0,1fr)}.inv-queue-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}.inv-issue-history{margin:0 0 20px;padding:18px;background:#f1f6eb;border-radius:10px;font-size:14px;overflow-wrap:anywhere}.inv-issue-history article{padding:14px 0;border-top:1px solid #dce6d4}.inv-issue-history p{font-size:13px;line-height:1.8;color:#73816c}.inv-issue-history h3{font-size:16px;margin:0 0 12px}</style>
